type Location = {
  index: number;
  line: number;
  column: number;
};

type TextNode = { type: "text"; value: string };
type ValueNode = {
  type: "value";
  path: string;
  escaped: boolean;
  location: Location;
};
type BlockNode = {
  type: "if" | "each";
  path: string;
  body: Node[];
  alternate: Node[];
  location: Location;
};
type Node = TextNode | ValueNode | BlockNode;

type Frame = {
  block: BlockNode;
  parent: Node[];
  inAlternate: boolean;
};

type RenderContext = {
  root: unknown;
  current: unknown;
  index?: number;
  inEach: boolean;
};

export class TemplateError extends Error {
  readonly line: number;
  readonly column: number;

  constructor(message: string, location: Location) {
    super(`${message} at line ${location.line}, column ${location.column}`);
    this.name = "TemplateError";
    this.line = location.line;
    this.column = location.column;
  }
}

function locationAt(source: string, index: number): Location {
  let line = 1;
  let column = 1;
  for (let i = 0; i < index; i++) {
    if (source.charCodeAt(i) === 10) {
      line++;
      column = 1;
    } else {
      column++;
    }
  }
  return { index, line, column };
}

function requirePath(path: string, description: string, location: Location): string {
  if (path.length === 0) {
    throw new TemplateError(`${description} requires a path`, location);
  }
  if (!/^(?:this|@index|[A-Za-z_$][\w$]*)(?:\.[A-Za-z_$][\w$]*)*$/.test(path)) {
    throw new TemplateError(`Invalid path "${path}"`, location);
  }
  return path;
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  const stack: Frame[] = [];
  let target = root;
  let cursor = 0;

  while (cursor < template.length) {
    const open = template.indexOf("{{", cursor);
    if (open === -1) {
      target.push({ type: "text", value: template.slice(cursor) });
      break;
    }
    if (open > cursor) {
      target.push({ type: "text", value: template.slice(cursor, open) });
    }

    const triple = template.startsWith("{{{", open);
    const closeToken = triple ? "}}}" : "}}";
    const contentStart = open + (triple ? 3 : 2);
    const close = template.indexOf(closeToken, contentStart);
    const location = locationAt(template, open);
    if (close === -1) {
      throw new TemplateError("Unclosed tag", location);
    }

    const content = template.slice(contentStart, close).trim();
    cursor = close + closeToken.length;

    if (triple) {
      target.push({
        type: "value",
        path: requirePath(content, "Interpolation", location),
        escaped: false,
        location,
      });
      continue;
    }

    if (content.startsWith("!")) continue;

    if (content.startsWith("#")) {
      const match = /^#(if|each)(?:\s+(.+?))?$/.exec(content);
      if (!match) {
        const name = content.slice(1).split(/\s/, 1)[0] || content;
        throw new TemplateError(`Unknown block "${name}"`, location);
      }
      const block: BlockNode = {
        type: match[1] as "if" | "each",
        path: requirePath(match[2]?.trim() ?? "", `#${match[1]}`, location),
        body: [],
        alternate: [],
        location,
      };
      target.push(block);
      stack.push({ block, parent: target, inAlternate: false });
      target = block.body;
      continue;
    }

    if (content === "else") {
      const frame = stack.at(-1);
      if (!frame) throw new TemplateError("{{else}} outside a block", location);
      if (frame.inAlternate) throw new TemplateError("Duplicate {{else}}", location);
      frame.inAlternate = true;
      target = frame.block.alternate;
      continue;
    }

    if (content.startsWith("/")) {
      const name = content.slice(1).trim();
      const frame = stack.at(-1);
      if (!frame) throw new TemplateError(`Closing block "${name}" without an open block`, location);
      if (name !== frame.block.type) {
        throw new TemplateError(
          `Mismatched closing block: expected "/${frame.block.type}" but found "/${name}"`,
          location,
        );
      }
      stack.pop();
      target = frame.parent;
      continue;
    }

    target.push({
      type: "value",
      path: requirePath(content, "Interpolation", location),
      escaped: true,
      location,
    });
  }

  const frame = stack.at(-1);
  if (frame) {
    throw new TemplateError(`Unclosed #${frame.block.type} block`, frame.block.location);
  }
  return root;
}

function hasProperty(value: unknown, key: string): value is Record<string, unknown> {
  return (typeof value === "object" && value !== null || typeof value === "function") && key in value;
}

function traverse(value: unknown, segments: string[]): unknown {
  let result = value;
  for (const segment of segments) {
    if (!hasProperty(result, segment)) return undefined;
    result = result[segment];
  }
  return result;
}

function resolve(path: string, context: RenderContext): unknown {
  const segments = path.split(".");
  if (segments[0] === "this") return traverse(context.current, segments.slice(1));
  if (segments[0] === "@index") {
    return segments.length === 1 && context.inEach ? context.index : undefined;
  }

  if (context.inEach) {
    const local = traverse(context.current, segments);
    if (local !== undefined) return local;
  }
  return traverse(context.root, segments);
}

function isTruthy(value: unknown): boolean {
  if (Array.isArray(value)) return value.length > 0;
  return Boolean(value);
}

function scalarToString(value: unknown, path: string, location: Location): string {
  if (value === null || value === undefined) return "";
  switch (typeof value) {
    case "string":
    case "number":
    case "bigint":
    case "boolean":
      return String(value);
    default:
      throw new TemplateError(`Value at "${path}" is not renderable as scalar text`, location);
  }
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case "\"": return "&quot;";
      default: return "&#39;";
    }
  });
}

function renderNodes(nodes: Node[], context: RenderContext): string {
  let output = "";
  for (const node of nodes) {
    if (node.type === "text") {
      output += node.value;
      continue;
    }
    if (node.type === "value") {
      const value = scalarToString(resolve(node.path, context), node.path, node.location);
      output += node.escaped ? escapeHtml(value) : value;
      continue;
    }

    const value = resolve(node.path, context);
    if (node.type === "if") {
      output += renderNodes(isTruthy(value) ? node.body : node.alternate, context);
      continue;
    }

    if (!Array.isArray(value) || value.length === 0) {
      output += renderNodes(node.alternate, context);
      continue;
    }
    for (let index = 0; index < value.length; index++) {
      output += renderNodes(node.body, {
        root: context.root,
        current: value[index],
        index,
        inEach: true,
      });
    }
  }
  return output;
}
import { render } from "./engine";

async function main(): Promise<void> {
  const [templatePath, dataPath, ...extra] = Bun.argv.slice(2);
  if (!templatePath || !dataPath || extra.length > 0) {
    throw new Error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  }

  const [template, json] = await Promise.all([
    Bun.file(templatePath).text(),
    Bun.file(dataPath).text(),
  ]);
  const data: unknown = JSON.parse(json);
  await Bun.write(Bun.stdout, render(template, data));
}

main().catch((error: unknown) => {
  const message = error instanceof Error ? error.message : String(error);
  console.error(`mini-template: ${message}`);
  process.exitCode = 1;
});
import { describe, expect, test } from "bun:test";
import { render, TemplateError } from "../src/engine";

describe("render", () => {
  test("interpolates, escapes HTML, and preserves whitespace", () => {
    expect(render(" A {{name}} / {{{name}}} Z\n", { name: "<&>\"'" })).toBe(
      " A &lt;&amp;&gt;&quot;&#39; / <&>\"' Z\n",
    );
  });

  test("renders missing values as empty strings and comments as nothing", () => {
    expect(render("x{{missing.deep}}y{{! ignored }}z", {})).toBe("xyz");
  });

  test("supports nested if blocks and specified truthiness", () => {
    const template = "{{#if outer}}A{{#if inner}}B{{else}}C{{/if}}{{else}}D{{/if}}";
    expect(render(template, { outer: true, inner: 0 })).toBe("AC");
    expect(render(template, { outer: [], inner: true })).toBe("D");
    expect(render("{{#if value}}T{{else}}F{{/if}}", { value: {} })).toBe("T");
  });

  test("iterates arrays with local values, index, root fallback, and nesting", () => {
    const template = "{{#each groups}}[{{name}}/{{title}}:{{#each this.items}}{{@index}}={{this}};{{else}}empty{{/each}}]{{else}}none{{/each}}";
    expect(render(template, {
      title: "root",
      groups: [
        { name: "a", items: ["x", "y"] },
        { name: "b", items: [] },
      ],
    })).toBe("[a/root:0=x;1=y;][b/root:empty]");
    expect(render("{{#each items}}x{{else}}none{{/each}}", { items: "no" })).toBe("none");
  });

  test("does not fall back when a local property exists with a null value", () => {
    expect(render("{{#each items}}{{name}}{{/each}}", {
      name: "root",
      items: [{ name: null }],
    })).toBe("");
  });

  test("rejects values that are not scalar text", () => {
    expect(() => render("value={{value}}", { value: { nested: true } })).toThrow(
      'Value at "value" is not renderable as scalar text at line 1, column 7',
    );
    expect(() => render("{{value}}", { value: () => 1 })).toThrow(TemplateError);
  });

  test.each([
    ["{{#wat x}}{{/wat}}", 'Unknown block "wat" at line 1, column 1'],
    ["one\n{{else}}", "{{else}} outside a block at line 2, column 1"],
    ["{{#if x}}{{else}}{{else}}{{/if}}", "Duplicate {{else}} at line 1, column 18"],
    ["{{#if x}}{{/each}}", 'Mismatched closing block: expected "/if" but found "/each" at line 1, column 10'],
    ["{{/if}}", 'Closing block "if" without an open block at line 1, column 1'],
    ["{{#each xs}}", "Unclosed #each block at line 1, column 1"],
    ["{{name", "Unclosed tag at line 1, column 1"],
  ])("reports structural error for %s", (template, message) => {
    expect(() => render(template, {})).toThrow(message);
  });
});
